{"content": "import pytest

import click


def test_version_option_with_version(runner):
    """Test that version_option works when version is provided
    explicitly, without needing package detection from the frame.
    """
    @click.command()
    @click.version_option(version="1.0")
    def cli():
        pass

    result = runner.invoke(cli, ["--version"])
    assert result.exit_code == 0
    assert "cli, version 1.0" in result.output


def test_version_option_with_package_name(runner):
    """Test that version_option works when package_name is provided
    explicitly, without needing frame inspection.
    """
    @click.command()
    @click.version_option(package_name="click")
    def cli():
        pass

    result = runner.invoke(cli, ["--version"])
    assert result.exit_code == 0
    assert "cli, version" in result.output", "path": "tests/test_version_option.py"}
